function makeT(lang) {
  const dict = DICTS[lang] ?? DICTS.zh
  return (key, vars) => {
    let text = dict[key] ?? DICTS.zh[key] ?? key
    if (vars) for (const [name, value] of Object.entries(vars)) text = text.replaceAll(`{${name}}`, String(value))
    return text
  }
}

const fallbackT = makeT('zh')

function dayKey(date = new Date()) {
  const y = date.getFullYear()
  const m = String(date.getMonth() + 1).padStart(2, '0')
  const d = String(date.getDate()).padStart(2, '0')
  return `${y}-${m}-${d}`
}

function readJson(key, fallback) {
  try {
    if (typeof localStorage === 'undefined') return fallback
    const raw = localStorage.getItem(key)
    return raw ? JSON.parse(raw) : fallback
  } catch {
    return fallback
  }
}

function writeJson(key, value) {
  try {
    if (typeof localStorage === 'undefined') return
    localStorage.setItem(key, JSON.stringify(value))
  } catch {
    /* storage can be unavailable; the UI still works in memory */
  }
}

async function api(path, init) {
  const response = await fetch(`${ROUTE}${path}`, { cache: 'no-store', ...init })
  let data = null
  try { data = await response.json() } catch { /* non-JSON */ }
  if (!response.ok || data?.ok === false) {
    const message = data?.error?.message ?? data?.error ?? `HTTP ${response.status}`
    throw new Error(typeof message === 'string' ? message : JSON.stringify(message))
  }
  return data
}

let commandSeq = 0
function commandId() {
  try {
    if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID()
  } catch { /* fall through */ }
  commandSeq += 1
  return `cwb-${Date.now()}-${commandSeq}`
}

async function sendCommand(type, payload) {
  return api('/command', {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ id: commandId(), type, payload }),
  })
}

class AppStore {
  constructor() {
    const cached = readJson(CACHE_KEY, null)
    this.snapshot = {
      state: cached?.state ?? null,
      summary: cached?.summary ?? null,
      packs: [],
      packData: {},
      packErrors: {},
      inbox: [],
      loading: !cached?.state,
      connected: false,
      error: '',
      lastRefresh: 0,
    }
    this.listeners = new Set()
    this.timer = null
    this.inflight = null
    this.lastCacheAt = 0
    this.started = false
    this.subscribe = (listener) => {
      this.listeners.add(listener)
      return () => this.listeners.delete(listener)
    }
    this.getSnapshot = () => this.snapshot
  }

  update(patch) {
    this.snapshot = { ...this.snapshot, ...patch }
    if ((this.snapshot.state || this.snapshot.summary) && Date.now() - this.lastCacheAt > 5000) {
      this.lastCacheAt = Date.now()
      writeJson(CACHE_KEY, { state: this.snapshot.state, summary: this.snapshot.summary, savedAt: Date.now() })
    }
    for (const listener of this.listeners) {
      try { listener() } catch { /* one bad listener must not stop others */ }
    }
  }

  async start() {
    if (this.started) return
    this.started = true
    this.timer = setInterval(() => { void this.refresh({ silent: true }) }, 60000)
    this.retryTimer = setInterval(() => {
      if (!this.snapshot.connected) void this.refresh({ silent: true })
    }, 5000)
    try {
      await this.refresh()
    } catch {
      /* keep retrying; the panel already has a read-only/error state */
    }
  }

  async refresh({ silent = false, force = false } = {}) {
    if (this.inflight) {
      if (!force) return this.inflight
      try { await this.inflight } catch { /* the forced attempt below decides */ }
    }
    const run = this.doRefresh({ silent })
    this.inflight = run
    try {
      return await run
    } finally {
      if (this.inflight === run) this.inflight = null
    }
  }

  async doRefresh({ silent = false } = {}) {
    try {
      const [stateRes, packsRes, inboxRes] = await Promise.all([
        api('/state'),
        api('/packs'),
        api('/inbox').catch(() => null),
      ])
      this.update({
        state: stateRes.state,
        summary: stateRes.summary ?? this.snapshot.summary,
        packs: packsRes.packs ?? [],
        inbox: inboxRes ? (inboxRes.items ?? []) : this.snapshot.inbox,
        connected: true,
        error: '',
        loading: false,
        lastRefresh: Date.now(),
      })
      if (stateRes.state?.settings?.onboardingDone) await this.loadEnabledPacks()
    } catch (error) {
      this.update({
        connected: false,
        error: error instanceof Error ? error.message : String(error),
        loading: false,
        lastRefresh: Date.now(),
      })
      if (!silent) throw error
    }
  }

  async loadPack(id) {
    if (this.snapshot.packData[id]) return this.snapshot.packData[id]
    try {
      const response = await api(`/packs/${encodeURIComponent(id)}`)
      const packData = { ...this.snapshot.packData, [id]: response.pack }
      const packErrors = { ...this.snapshot.packErrors }
      delete packErrors[id]
      this.update({ packData, packErrors })
      return response.pack
    } catch (error) {
      this.update({ packErrors: { ...this.snapshot.packErrors, [id]: error instanceof Error ? error.message : String(error) } })
      return null
    }
  }

  async loadEnabledPacks() {
    const enabled = this.snapshot.state?.settings?.packs?.enabled ?? []
    await Promise.all(enabled.map((id) => this.loadPack(id)))
  }

  async send(type, payload) {
    try {
      const result = await sendCommand(type, payload)
      await this.refresh({ silent: true, force: true })
      return result
    } catch (error) {
      this.update({ error: error instanceof Error ? error.message : String(error) })
      throw error
    }
  }

  dispose() {
    if (this.timer) clearInterval(this.timer)
    if (this.retryTimer) clearInterval(this.retryTimer)
    this.timer = null
    this.retryTimer = null
    this.listeners.clear()
  }
}

class BadgeStore {
  constructor(app) {
    this.app = app
    this.listeners = new Set()
    this.openedDay = readJson(BADGE_KEY, {})?.openedDay ?? ''
    this.forceUntil = 0
    this.timer = null
    this.previewTimer = null
    this.panelOpen = false
    this.cleanups = []
    this.snapshot = { on: false, reason: '' }
    this.subscribe = (listener) => {
      this.listeners.add(listener)
      return () => this.listeners.delete(listener)
    }
    this.getSnapshot = () => this.snapshot
    this.appUnsubscribe = app.subscribe(() => this.compute())
    this.compute()
  }

  set(next) {
    if (next.on === this.snapshot.on && next.reason === this.snapshot.reason) return
    this.snapshot = next
    for (const listener of this.listeners) {
      try { listener() } catch { /* ignore */ }
    }
  }

  compute() {
    const { state, summary } = this.app.getSnapshot()
    const enabled = state?.settings?.enabled !== false && state?.settings?.badge?.enabled !== false
    const today = dayKey()
    if (this.panelOpen && this.openedDay !== today) {
      this.openedDay = today
      writeJson(BADGE_KEY, { openedDay: this.openedDay })
    }
    const acted = summary?.actedToday === true
    const pending = (summary?.dueCount ?? 0) > 0 || (summary?.newAutoCount ?? 0) > 0
    let on = false
    let reason = ''
    if (Date.now() < this.forceUntil) {
      on = true
      reason = 'preview'
    } else if (enabled) {
      if (acted) {
        on = false
      } else if (pending) {
        on = true
        reason = 'pending'
      } else if (this.openedDay !== today) {
        on = true
        reason = 'daily'
      }
    }
    this.set({ on, reason })
  }

  markOpened() {
    this.openedDay = dayKey()
    writeJson(BADGE_KEY, { openedDay: this.openedDay })
    this.compute()
  }

  preview() {
    this.forceUntil = Date.now() + 60000
    this.compute()
    if (this.previewTimer) clearTimeout(this.previewTimer)
    this.previewTimer = setTimeout(() => {
      this.previewTimer = null
      this.compute()
    }, 61000)
    this.previewTimer?.unref?.()
  }

  start(layout) {
    this.compute()
    if (layout?.panelInfo?.subscribe) {
      try {
        const dispose = layout.panelInfo.subscribe(() => {
          const active = layout.panelInfo.getSnapshot?.().activePanelId
          this.panelOpen = active === PANEL_ID
          if (active === PANEL_ID) this.markOpened()
          else this.compute()
        })
        if (typeof dispose === 'function') this.cleanups.push(dispose)
        const active = layout.panelInfo.getSnapshot?.().activePanelId
        this.panelOpen = active === PANEL_ID
        if (active === PANEL_ID) this.markOpened()
      } catch { /* layout is optional */ }
    }
    this.timer = setInterval(() => this.compute(), 60000)
    if (typeof addEventListener === 'function') {
      const onFocus = () => this.compute()
      const onVisibility = () => this.compute()
      addEventListener('focus', onFocus)
      addEventListener('visibilitychange', onVisibility)
      this.cleanups.push(() => {
        if (typeof removeEventListener === 'function') {
          removeEventListener('focus', onFocus)
          removeEventListener('visibilitychange', onVisibility)
        }
      })
    }
    return () => {
      if (this.timer) clearInterval(this.timer)
      if (this.previewTimer) clearTimeout(this.previewTimer)
      this.timer = null
      this.previewTimer = null
      for (const cleanup of this.cleanups) {
        try { cleanup() } catch { /* ignore */ }
      }
      this.cleanups = []
      this.appUnsubscribe?.()
      this.listeners.clear()
    }
  }
}

let app = null
let badge = null

const EMPTY_SUBSCRIBE = () => () => {}
const EMPTY_GET = () => null

function useApp() {
  return useSyncExternalStore(app?.subscribe ?? EMPTY_SUBSCRIBE, app?.getSnapshot ?? EMPTY_GET)
}

function useBadge() {
  return useSyncExternalStore(badge?.subscribe ?? EMPTY_SUBSCRIBE, badge?.getSnapshot ?? EMPTY_GET) ?? { on: false, reason: '' }
}

